/**
 * Dashboard Render Helpers
 *
 * Handles rendering of various dashboard data elements
 *
 * @package ContactInbox\Dashboard\JS
 */

// Ensure $ refers to jQuery in WordPress noConflict mode
const $ = window.jQuery || jQuery;

const DashboardRenderHelpers = {
    /**
     * Render CRM endpoints table
     */
    renderCRMEndpoints(endpoints) {
        const container = $('#crm-endpoints');
        try {
            if (!endpoints || endpoints.length === 0) {
                container.html('<p class="placeholder-text">No endpoint data available</p>');
                return;
            }

            let html = '<table class="endpoints-table"><thead><tr><th>Endpoint</th><th>Calls</th><th>Success Rate</th></tr></thead><tbody>';
            endpoints.forEach((ep, index) => {
                const total = ep.total || 0;
                const successful = ep.successful || 0;
                const failed = ep.failed || 0;
                const attempted = successful + failed;
                const rate = attempted > 0 ? ((successful / attempted) * 100).toFixed(1) : '0.0';
                const label = ep.display_name || ep.endpoint || 'Unknown';
                html += `<tr><td>${label}</td><td>${total}</td><td><span class="success-badge">${rate}%</span></td></tr>`;
            });
            html += '</tbody></table>';
            container.html(html);
        } catch (e) {
            container.html('<p class="placeholder-text">Endpoint data unavailable</p>');
        }
    },

    /**
     * Render CRM activity log table
     */
    renderCRMActivityLog(logs) {
        const container = $('#crm-activity-log');

        if (!logs || logs.length === 0) {
            container.html('<p class="placeholder-text">No recent activity</p>');
            return;
        }

        const formatEndpoint = (endpoint) => {
            if (!endpoint) return 'Unknown';
            try {
                const url = new URL(endpoint);
                return url.pathname.split('/').filter(Boolean).slice(-2).join('/') || endpoint;
            } catch (e) {
                return endpoint.length > 80 ? `${endpoint.slice(0, 77)}...` : endpoint;
            }
        };

        const parseResponse = (raw) => {
            if (!raw) return {};
            if (typeof raw === 'object') return raw;
            try {
                return JSON.parse(raw);
            } catch (e) {
                return {};
            }
        };

        const normalizeStatus = (raw) => {
            const val = (raw || '').toString().toLowerCase();
            if (['delivered', 'success', 'ok'].includes(val)) return { label: 'Delivered', cls: 'success' };
            if (['rejected', 'server_error', 'connection_failed', 'failed', 'error', 'timeout'].includes(val)) return { label: 'Error', cls: 'error' };
            if (['pending', 'queued'].includes(val)) return { label: 'Pending', cls: 'warning' };
            return { label: raw || 'Unknown', cls: 'warning' };
        };

        let html = '<table class="activity-table"><thead><tr><th>Time</th><th>Type</th><th>Status</th><th>Message</th></tr></thead><tbody>';
        logs.slice(0, 10).forEach((log) => {
            const statusInfo = normalizeStatus(log.crm_send_status || log.status);
            const time = log.timestamp || log.created_at || 'N/A';
            const response = parseResponse(log.response);
            const endpoint = response.endpoint || log.crm_endpoint || '';
            const type = log.operation || formatEndpoint(endpoint) || 'Unknown';
            const message = log.error_message || response.error_message || log.message || log.crm_response_body || 'No message';
            html += `<tr><td>${time}</td><td>${type}</td><td><span class="status-badge ${statusInfo.cls}">${statusInfo.label}</span></td><td>${message}</td></tr>`;
        });
        html += '</tbody></table>';
        container.html(html);
    },

    /**
     * Render queue stats card
     */
    renderQueueStats(data) {
        if (!data.queues) return;

        const queueStatusGrid = $('.queue-status-grid');
        let queueHtml = '';

        // Render queue cards
        for (const [type, queue] of Object.entries(data.queues)) {
            const counts = queue.counts || {};
            queueHtml += `
                <div class="analytics-card queue-card queue-${type}">
                    <div class="queue-card-head">
                        <div class="queue-card-title">
                            <span class="queue-name">${queue.label}</span>
                            <span class="queue-chip state-${queue.state}">${queue.state_label}</span>
                        </div>
                        <div class="queue-total">
                            <span class="queue-total-label">Pending</span>
                            <span class="queue-total-value">${counts.pending || 0}</span>
                        </div>
                    </div>
                    <div class="queue-counts">
                        <div class="queue-stat">
                            <span class="stat-label">Sent</span>
                            <span class="stat-value">${counts.sent || 0}</span>
                        </div>
                        <div class="queue-stat">
                            <span class="stat-label">Failed</span>
                            <span class="stat-value">${counts.dlq || 0}</span>
                        </div>
                    </div>
                </div>
            `;
        }

        // Render DLQ summary card
        queueHtml += `
            <div class="analytics-card queue-card queue-dlq">
                <div class="queue-card-head">
                    <div class="queue-card-title">
                        <span class="queue-name">Dead Letter (All Types)</span>
                        <span class="queue-chip state-${data.dlq_state}">${data.dlq_label}</span>
                    </div>
                    <div class="queue-total">
                        <span class="queue-total-label">Total</span>
                        <span class="queue-total-value">${data.dlq_total}</span>
                    </div>
                </div>
                <p class="queue-help-text">Messages moved here after max retries are exceeded.</p>
            </div>
        `;

        // Update the grid (remove old cards first, keep the header)
        queueStatusGrid.find('.queue-card').remove();
        queueStatusGrid.append(queueHtml);
    },

    /**
     * Get health status label for cron jobs
     */
    getHealthLabel(health) {
        if (health === 'healthy' || health === 'good') return 'Healthy';
        if (health === 'warning') return 'Warning';
        if (health === 'critical' || health === 'error') return 'Critical';
        if (typeof health === 'number') return `${health}%`;
        return '—';
    },

    /**
     * Format cron hook name for display
     */
    formatCronName(hook) {
        const map = {
            contactinbox_process_email_queue: 'Email Queue Processor',
            contactinbox_process_crm_queue: 'CRM Queue Processor',
            contactinbox_cleanup_cron: 'Cleanup',
            contactinbox_gdpr_expiry_check: 'GDPR Expiry',
            contactin_daily_analytics_aggregation: 'Analytics Aggregation',
            contactinbox_process_queue: 'Queue Processor (Legacy)',
        };
        return map[hook] || hook;
    },

    /**
     * Update cron card with status and metadata
     */
    updateCronCard(hook, data) {
        const statusEl = $(`#cron-${hook}-status`);
        const metaEl = $(`#cron-${hook}-meta`);

        if (!statusEl.length || !metaEl.length) return;

        if (!data) {
            statusEl.text('Not yet run');
            metaEl.find('[data-field="last_run"]').text('—');
            metaEl.find('[data-field="next_run"]').text('—');
            metaEl.find('[data-field="failure_count"]').text('0');
            metaEl.find('[data-field="last_duration_ms"]').text('—');
            metaEl.find('[data-field="items_processed"]').text('0');
            return;
        }

        statusEl.text(this.getHealthLabel(data.health));
        metaEl.find('[data-field="last_run"]').text(data.last_run ? DashboardDateUtils.formatDate(data.last_run) : 'Never');
        metaEl.find('[data-field="next_run"]').text(DashboardDateUtils.formatDate(data.next_run));
        metaEl.find('[data-field="failure_count"]').text(data.failure_count ?? 0);
        metaEl.find('[data-field="last_duration_ms"]').text(DashboardDateUtils.formatDuration(data.last_duration_ms));
        metaEl.find('[data-field="items_processed"]').text(data.items_processed ?? 0);
    },

    /**
     * Get health status class from status string
     */
    getHealthStatus(status) {
        if (!status) return 'good';
        const lower = `${status}`.toLowerCase();
        if (lower.includes('good') || lower.includes('healthy')) return 'good';
        if (lower.includes('warning')) return 'warning';
        return 'error';
    },
};
